#include <Arduino.h>
#include <TFT_eSPI.h>

// Definicja pinów specyficznych dla LilyGo T-Embed (ESP32-S3 + ST7789)
#define PIN_POWER_ON 15 // Pin włączający zasilanie peryferiów
#define PIN_LCD_BL   21 // Pin sterujący podświetleniem ekranu (Backlight)

// Inicjalizacja instancji wyświetlacza
TFT_eSPI tft = TFT_eSPI();

void setup() {
    // Inicjalizacja portu szeregowego
    Serial.begin(115200);
    delay(500);

    Serial.println();
    Serial.println("--- LILYGO T-EMBED ---");
    Serial.println("DISPLAY TEST V3");

    // 1. KROK: Włączenie głównego zasilania dla peryferiów (CC1101, LCD itp.)
    pinMode(PIN_POWER_ON, OUTPUT);
    digitalWrite(PIN_POWER_ON, HIGH);
    delay(200); // Czas na ustabilizowanie napięcia

    // 2. KROK: Inicjalizacja biblioteki graficznej przed włączeniem podświetlenia
    Serial.println("Initializing TFT...");
    tft.init();

    // Ustawienie rotacji dla T-Embed (3 = pozioma, złącze USB po lewej)
    tft.setRotation(3); 

    // Czyszczenie ekranu przed włączeniem światła (unikamy śmieci na ekranie)
    tft.fillScreen(TFT_BLACK); 

    // 3. KROK: Włączenie podświetlenia ekranu
    pinMode(PIN_LCD_BL, OUTPUT);
    digitalWrite(PIN_LCD_BL, HIGH);
    delay(100);

    // Wypisanie rozdzielczości w konsoli (Dla T-Embed powinno być 320x170)
    Serial.print("Resolution: ");
    Serial.print(tft.width());
    Serial.print("x");
    Serial.println(tft.height());

    // --- SEKWENCJA TESTU KOLORÓW ---
    Serial.println("Color test...");

    tft.fillScreen(TFT_RED);
    delay(500);

    tft.fillScreen(TFT_GREEN);
    delay(500);

    tft.fillScreen(TFT_BLUE);
    delay(500);

    // --- EKRAN KOŃCOWY ---
    tft.fillScreen(TFT_BLACK);

    // Rysowanie ramki na krawędziach ekranu
    tft.drawRect(0, 0, tft.width(), tft.height(), TFT_CYAN);

    // Ustawienia tekstu
    tft.setTextColor(TFT_WHITE, TFT_BLACK);

    // Wyśrodkowany napis LILYGO
    tft.setTextSize(3);
    tft.setCursor((tft.width() - tft.textWidth("LILYGO")) / 2, 35);
    tft.println("LILYGO");

    // Wyśrodkowany napis STATUSU
    tft.setTextSize(2);
    tft.setTextColor(TFT_GREEN, TFT_BLACK);
    tft.setCursor((tft.width() - tft.textWidth("DISPLAY OK")) / 2, 80);
    tft.println("DISPLAY OK");

    // Informacja o sterowniku na dole
    tft.setTextSize(1);
    tft.setTextColor(TFT_LIGHTGRAY, TFT_BLACK);
    tft.setCursor((tft.width() - tft.textWidth("ST7789 (320x170)")) / 2, 130);
    tft.println("ST7789 (320x170)");

    Serial.println("DISPLAY TEST FINISHED");
}

void loop() {
    // Pusta pętla - program wykonał się w setup()
    delay(1000);
}
